REVOKE SELECT, USAGE ON SEQUENCE public."DemonRecords_id_seq" FROM anon;
REVOKE SELECT, USAGE ON SEQUENCE public."DemonRecords_id_seq" FROM authenticated;
REVOKE SELECT, USAGE ON SEQUENCE public."DemonRecords_id_seq" FROM service_role;
REVOKE SELECT, USAGE ON SEQUENCE public."ImportJobs_id_seq" FROM anon;
REVOKE SELECT, USAGE ON SEQUENCE public."ImportJobs_id_seq" FROM authenticated;
REVOKE SELECT, USAGE ON SEQUENCE public."ImportJobs_id_seq" FROM service_role;
CREATE SEQUENCE public."SimpleStatsCache_id_seq";
REVOKE DELETE, INSERT, SELECT, UPDATE ON public."ImportJobs" FROM anon;
CREATE TABLE public."SimpleStatsCache" (id bigint DEFAULT nextval('public."SimpleStatsCache_id_seq"'::regclass) NOT NULL, group_id bigint NOT NULL, species_id bigint NOT NULL, temporal_unit text NOT NULL, time_period date NOT NULL, species_count bigint NOT NULL, bird_count bigint NOT NULL, encounter_count bigint NOT NULL, new_bird_count bigint NOT NULL, session_count bigint NOT NULL, total_effort interval NOT NULL, effort_per_session interval NOT NULL, effort_per_encounter interval NOT NULL, avg_encounters_per_session numeric NOT NULL, max_per_session bigint NOT NULL, max_new_per_session bigint NOT NULL, max_weight real, avg_weight numeric, min_weight real, median_weight numeric, max_wing smallint, avg_wing numeric, min_wing smallint, median_wing numeric, pullus_bird_count bigint NOT NULL, juv_bird_count bigint NOT NULL, postjuv_bird_count bigint NOT NULL, adult_bird_count bigint NOT NULL, unknown_age_bird_count bigint NOT NULL, new_young_bird_count bigint NOT NULL, pullus_enc_count bigint NOT NULL, juv_enc_count bigint NOT NULL, postjuv_enc_count bigint NOT NULL, adult_enc_count bigint NOT NULL, unknown_age_enc_count bigint NOT NULL, postjuv_juv_enc_count bigint NOT NULL, new_postjuv_juv_enc_count bigint NOT NULL, new_postjuv_enc_count bigint NOT NULL);
ALTER SEQUENCE public."SimpleStatsCache_id_seq" OWNED BY public."SimpleStatsCache".id;
GRANT UPDATE ON SEQUENCE public."SimpleStatsCache_id_seq" TO anon;
GRANT UPDATE ON SEQUENCE public."SimpleStatsCache_id_seq" TO authenticated;
GRANT UPDATE ON SEQUENCE public."SimpleStatsCache_id_seq" TO service_role;
COMMENT ON TABLE public."SimpleStatsCache" IS 'One row per (group_id, species_id, temporal_unit, time_period): every period-local metric shared between core_stats_result, biometrics_stats_result and demographics_stats_result. Lifetime-relative demographics columns live in the separate ComplexStatsCache table instead.';
COMMENT ON COLUMN public."SimpleStatsCache".time_period IS 'Sentinel value 0001-01-01 for the all-time grain, never real data. This table uses a fixed sentinel instead of NULL (unlike core_stats/biometrics_stats/demographics_stats) so a single plain UNIQUE constraint covers every grain.';
ALTER TABLE public."SimpleStatsCache" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."SimpleStatsCache" ADD CONSTRAINT "SimpleStatsCache_pkey" PRIMARY KEY (id);
ALTER TABLE public."SimpleStatsCache" ADD CONSTRAINT simple_stats_cache_group_id_fkey FOREIGN KEY (group_id) REFERENCES public."RingingGroups"(id);
ALTER TABLE public."SimpleStatsCache" ADD CONSTRAINT simple_stats_cache_group_species_grain_period_key UNIQUE (group_id, species_id, temporal_unit, time_period);
ALTER TABLE public."SimpleStatsCache" ADD CONSTRAINT simple_stats_cache_species_id_fkey FOREIGN KEY (species_id) REFERENCES public."Species"(id);
ALTER TABLE public."SimpleStatsCache" ADD CONSTRAINT simple_stats_cache_temporal_unit_check CHECK (temporal_unit = ANY (ARRAY['day'::text, 'month'::text, 'year'::text, 'month-squashed'::text, 'all-time'::text]));
GRANT INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON public."SimpleStatsCache" TO authenticated;
GRANT ALL ON public."SimpleStatsCache" TO service_role;
CREATE INDEX idx_simple_stats_cache_group_id ON public."SimpleStatsCache" (group_id);
CREATE POLICY group_simple_stats_cache_access ON public."SimpleStatsCache" FOR SELECT USING ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
CREATE POLICY group_simple_stats_cache_insert ON public."SimpleStatsCache" FOR INSERT WITH CHECK ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
CREATE POLICY group_simple_stats_cache_update ON public."SimpleStatsCache" FOR UPDATE USING ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint)) WITH CHECK ((group_id = (((auth.jwt() -> 'app_metadata'::text) ->> 'ringing_group_id'::text))::bigint));
